def lcp(s1, s2):
    i = 0
    while i < len(s1) and i < len(s2):
        if s1[i] != s2[i]:
            break
        i += 1
    return i

def find_max_representation(proteins, k):
    n = len(proteins)
    proteins.sort(key=lambda x: len(x))
    return max_representivity(proteins, n, k)

def max_representivity(proteins, n, k):
    def dp(i, j):
        if j < k + 1:
            return 0
        if dp.memo[i][j] >= 0:
            return dp.memo[i][j]
        res = proteins[i][-1]
        for j in range(k + 1):
            ij = proteins[i][j]
            persist = 0
            for si in range(k + 1):
                sj = proteins[i + si][j]
                if lcp(ij, sj) >= k - 1 - si:
                    persist = max(dp(i + si + 1, sj) + len(sj), persist)
            res = max(res, persist)
        dp.memo[i][j] = res
        return res

    dp.memo = [[-1] * (k + 1) for _ in range(n)]
    return dp(0, 0)

