import collections

class BridgeClub:
    def maxMoney(self, topics: int, limitPairs: int, playerValues: list) -> int:
        bitCount = countBits(topics)
        curMax = 0

        for i in range(limitPairs):
            tempCost = 0
            for j in range(topics):
                if not isRelative(i, j, bitCount):
                    tempCost += playerValues[j]
            if tempCost > curMax:
                curMax = tempCost
        return curMax

    def countBits(self, num):
        return bin(num).count("1")

    def isRelative(self, index1, index2, bitCount):
        diff = index1 ^ index2
        for i in range(bitCount - 1, -1, -1):
            if (diff >> i) & 1:
                return True
        return False

    def getOrder(self, index1, index2, bits):
        bitMap = [0] * len(bits)
        diffIndex = index1 ^ index2
        for i in range(len(bits) - 1, -1, -1):
            bit = bits[i]
            if (diffIndex >> i) & 1:
                bitMap[i] = bit
        return 1 << index1 & bitMap | 1 << index2 & bitMap


# Example usage
pq = BridgeClub()
print(pq.maxMoney(3, 1, [8, 3, 5, 7, 1, 10, 3, 2]))  # Output: 13
print(pq.maxMoney(2, 3, [7, 4, 5, 7]))  # Output: 23
