    for i in range(len(comb)):
        if check_for_combination(comb, i, negativity, target):
            break
    else:
        return False
    return True

def check_for_combination(comb, i, negativity, target):
    c = [binary_to_number(comb[j]) for j in range(len(comb) - 1)]
    for j in range(i):
        a, b, c = comb[j], comb[j + 1], c
