                return True
    return True

def binary_to_number(num):
    nums = [num >> i for i in range(floor(log2(len(num))) + 1)]
    return sum(y * (1 << x) for x, y in enumerate(nums))

@cache
def score_range(comb, left, right):
    a, b, c = binary_to_number(comb[0]), binary_to_number(comb[1]), None
    for i in range(right):
        diff = c = -a - b + (1 << (log2(right) + i))
        for j in range(i + 1, len(comb)):
            a, b = comb[j - 1], comb[j]
            diff -= ((((-1) ** i) if (((-1) ** j) != (i - j)) else 0) * b | a)
