def visit(index, visited, road_graph, answer):
    try:
        return answer[road_graph[index].index(index)]
    except ValueError:
        pass

    for next_index in road_graph[index]:
        if next_index not in visited:
            visited.add(next_index)
            answer = visit(next_index, visited, road_graph, answer)
            visited.remove(next_index)
    return answer

