import heapq

def find_path(graph, start):
    visited = set()
    queue = [(start, 0)]
    directions = "LR"

    while queue:
        current, direction = heapq.heappop(queue)
        if current in visited:
            break
        visited.add(current)
        if direction == "L":
            alternate_direction = "R"
        else:
            alternate_direction = "L"
        for adjacent in graph[current]:
            heapq.heappush(queue, (adjacent, alternate_direction))
    return visited, directions

def topath(directions):
    return ['To'] + directions + ['From']

def min_cables_to_configure(graph):
    visited, initial_direction = find_path(graph, 1)
    direction_to_node = {node: initial_direction for node in graph if node not in visited}
    sources = {node: direction for node, direction in direction_to_node.items() if node == int(direction)}
    sinks = {node: direction for node, direction in direction_to_node.items() if node != int(direction) == 'L'}
    def find_best_direction(node, drain):
        drained = []
        not_drained = []
        for other_node in graph:
            parametr = [(graph[other_node][node], direction) for direction in ('R', 'L') if graph[other_node][node] is not None and (direction in ('R', 'L') or other_node not in not_drained)][0]
            if parametr[0] == drain and parametr[1] == 'R':
                remain = graph[node][other_node]
            elif graph[node][other_node] is not None and (not_drained == []) and graph[node][other_node] < remain:
                not_drained.append(other_node)
                continue
            drained.append(parametr)
        no_drain, drained = max(drained, key=lambda x: int(x[0]))
        return (drain, int(no_drain[0]), topath(['To']+[node]+[direction_to_node node] for node in no_drain) if drain != no_drain else ('R', 'To', sources[argmax(sources, key=int)])
    # Handle single-source case
    if not sources and not sinks:
        sources = sources.pop()
    drain = max(sinks, key=lambda node: abs(int(sinks[node][0])))
    return find_best_direction(drain, drain) is not None

