import bisect

def calculate_time_to_never_see():
    n, m = map(int, input().split())
    walls = [input().split() for _ in range(m)]
    timestamps = list(map(int, input().split()))
    f1, f2, t = map(lambda x: tuple(map(int, x.split())), walls)

    results = set()

    for x in timestamps:
        binary_peek_1 = bisect.bisect_right(walls, (x, t)) - 1
        binary_peek_2 = bisect.bisect_right(walls, (x, t+1)) - 1

        ceil = max(f1[1], f2[1])
        floor = min(f1[0], f2[0])

        if ceil < x < floor:
            continue

        if binary_peek_1 >= 0 and ceil < t and x > t:
            floor = x + t - 1
        elif binary_peek_2 >= 0 and ceil < t and x > t:
            floor = x + t - 1

        if x < floor:
            results.add(x + abs(floor - x) - 1)

    return sorted(results)

