def find_minimum_transit_time(city1, city2, cannons, seconds=1):
    """Find the minimum time to transit between two cities using cannons."""
    remaining_cannon = city1
    seconds_passed = 0

    while remaining_cannon != city2:
        if manhattan_distance(remaining_cannon, city2) <= seconds:
            return seconds_passed + manhattan_distance(city2, city1)
        else:
            translate_diff = (city2 - city1 - 1) % (max(city2, city1) - min(city2, city1) + 1)
            seconds_passed += translate_diff
            remaining_cannon = (remaining_cannon + translate_diff) % (len(cannons))

    return seconds_passed + manhattan_distance(city2, city1)

