def protein_representativity(proteins: List[str], subset: List[int]) -> int:
    max_rep = 0
    for start in range(len(subset)):
        for end in range(start, len(subset)):
            length = len(proteins[subset[end]])
            prefix_count = 0
            for i in range(min(len(proteins[start]), len(proteins[end]))):
                prefix_count += longest_common_prefix(proteins[start][i:], proteins[end][i:])
            max_rep = max(max_rep, length - prefix_count)
    return max_rep

